(5, 1, '2026-10-09 03:14:11', '2026-10-09 00:14:11', '<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group -->\n<div class=\"wp-block-group\"><div class=\"wp-block-group__inner-container\"><!-- wp:group -->\n<div class=\"wp-block-group\"><div class=\"wp-block-group__inner-container\"></div></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:group -->\n\n<!-- wp:media-text {\"mediaId\":29,\"mediaLink\":\"http://mysite1.ru/%d0%b3%d0%bb%d0%b0%d0%b2%d0%bd%d0%b0%d1%8f/diplom-2/\",\"mediaType\":\"image\",\"mediaWidth\":25} -->\n<div class=\"wp-block-media-text alignwide is-stacked-on-mobile\" style=\"grid-template-columns:25% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://mysite1.ru/wp-content/uploads/2026/10/diplom-1.png\" alt=\"\" class=\"wp-image-29\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph -->\n<p>Свет, пространство и вдохновение для ваших съёмок</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"placeholder\":\"Содержимое...\",\"customFontSize\":39.25} -->\n<p style=\"font-size:39.25px\">Добро пожаловать в фотостудию \"Объектив\"!</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Мы предлагаем:<br>• Профессиональный свет<br>• Высокие потолки<br>• Гримерка<br>• Несколько залов с разными интерьерами</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:group -->\n<div class=\"wp-block-group\"><div class=\"wp-block-group__inner-container\"><!-- wp:group -->\n<div class=\"wp-block-group\"><div class=\"wp-block-group__inner-container\"></div></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:group -->\n\n<!-- wp:group -->\n<div class=\"wp-block-group\"><div class=\"wp-block-group__inner-container\"></div></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', 'Главная', '', 'publish', 'closed', 'closed', '', '%d0%b3%d0%bb%d0%b0%d0%b2%d0%bd%d0%b0%d1%8f', '', '', '2026-10-09 04:03:01', '2026-10-09 01:03:01', '', 0, 'http://mysite1.ru/?page_id=5',