(24, 1, '2026-10-09 03:43:50', '2026-10-09 00:43:50', '{\n    \"twentytwenty::blog_content\": {\n        \"value\": \"full\",\n        \"type\": \"theme_mod\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-10-09 00:41:31\"\n    },\n    \"custom_css[twentytwenty]\": {\n        \"value\": \"/* \\u0417\\u0430\\u0433\\u043e\\u043b\\u043e\\u0432\\u043e\\u043a \\u0441\\u0442\\u0440\\u0430\\u043d\\u0438\\u0446\\u044b \\u2014 \\u043c\\u0430\\u043b\\u0435\\u043d\\u044c\\u043a\\u0438\\u0439 \\u0438 \\u0441\\u043b\\u0435\\u0432\\u0430 */\\n.entry-title {\\n    font-size: 32px !important;\\n    text-align: left !important;\\n    margin-left: 20px !important;\\n    margin-bottom: 20px !important;\\n    font-weight: normal !important;\\n}\\n\\n/* \\u0423\\u0431\\u0438\\u0440\\u0430\\u0435\\u043c \\u043f\\u043e\\u0434\\u0437\\u0430\\u0433\\u043e\\u043b\\u043e\\u0432\\u043e\\u043a \\\"\\u0415\\u0449\\u0451 \\u043e\\u0434\\u0438\\u043d \\u0441\\u0430\\u0439\\u0442 \\u043d\\u0430 WordPress\\\" */\\n.site-description {\\n    display: none !important;\\n}\",\n        \"type\": \"custom_css\",\n        \"user_id\": 1,\n        \"date_modified_gmt\": \"2026-10-09 00:43:26\"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', '6be469c0-4e2c-47b6-a456-71f20c6de675', '', '', '2026-10-09 03:43:50', '2026-10-09 00:43:50', '', 0, 'http://mysite1.ru/?p=24', 0, 'customize_changeset', '', 0),
