(28, 1, '2026-10-09 03:56:20', '2026-10-09 00:56:20', '<!-- wp:html -->\n<div style=\"display: flex; align-items: center; gap: 40px; max-width: 1000px; margin: 0 auto; padding: 40px 20px; flex-wrap: wrap;\">\n  \n  <!-- Текст слева -->\n  <div style=\"flex: 1; min-width: 300px;\">\n    <h2 style=\"font-size: 32px; margin-bottom: 20px; color: #333;\">Свет, пространство и вдохновение для ваших съёмок</h2>\n    <p style=\"font-size: 18px; line-height: 1.6; color: #555;\">Добро пожаловать в фотостудию «Объектив»!</p>\n    <p style=\"font-size: 18px; margin-top: 20px; color: #555;\">Мы предлагаем:</p>\n    <ul style=\"font-size: 18px; line-height: 2; color: #555;\">\n      <li>Профессиональный свет</li>\n      <li>Высокие потолки</li>\n      <li>Гримерка</li>\n      <li>Несколько залов с разными интерьерами</li>\n    </ul>\n  </div>\n  \n  <!-- Фото справа (твоя ссылка уже вставлена!) -->\n  <div style=\"flex: 1; min-width: 300px;\">\n    <img src=\"http://mysite1.ru/wp-content/uploads/2026/10/diplom.png\" alt=\"Фотостудия Объектив\" style=\"width: 100%; border-radius: 15px; box-shadow: 0 10px 30px rgba(0,0,0,0.15);\">\n  </div>\n  \n</div>\n<!-- /wp:html -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', 'Главная', '', 'inherit', 'closed', 'closed', '', '5-autosave-v1', '', '', '2026-10-09 03:56:20', '2026-10-09 00:56:20', '', 5, 'http://mysite1.ru/2026/10/09/5-autosave-v1/', 0, 'revision', '', 0),
